import Component from 'flarum/common/Component';
import t from '../t';

/**
 * What changed on this forum, and when — the "recently updated" list an app
 * store keeps. Read from storage/millwright/history.json (see History.php).
 */
export default class HistoryTab extends Component {
  view() {
    const history = this.attrs.history || [];
    if (!history.length) return m("div", {
      className: "Millwright-empty"
    }, t('history_empty'));
    const names = {};
    (this.attrs.installed || []).forEach(e => names[e.package] = e.name);
    names['flarum/core'] = names['flarum/core'] || 'Flarum';
    return m("ol", {
      className: "Millwright-history"
    }, history.map(entry => {
      // The packages somebody asked for lead; what came along with them follows.
      const changes = [...(entry.changes || [])].sort((a, b) => Number((entry.requested || []).includes(b.package)) - Number((entry.requested || []).includes(a.package)));
      const when = dayjs(entry.at * 1000);
      return m("li", {
        key: entry.id,
        className: 'Millwright-historyItem is-' + entry.state
      }, m("div", {
        className: "Millwright-historyHead"
      }, m("span", {
        className: 'Millwright-tag' + this.tone(entry.state)
      }, t('history_' + this.outcome(entry))), m("time", {
        datetime: when.toISOString(),
        title: when.format('LLLL')
      }, when.format('LLL'))), m("ul", {
        className: "Millwright-historyChanges"
      }, changes.length ? changes.map(c => m("li", {
        key: c.package
      }, m("b", null, names[c.package] || c.package), " ", m("span", {
        className: "Millwright-pkg"
      }, c.package), ' ', m("span", {
        className: "Millwright-historyVersions"
      }, c.op === 'add' ? t('history_new', {
        version: c.to
      }) : c.op === 'remove' ? t('history_removed_from', {
        version: c.from
      }) : `${c.from} → ${c.to}`))) : m("li", null, (entry.requested || []).join(', ') || t('history_nothing'))), entry.migrations > 0 ? m("div", {
        className: "Millwright-historyNote"
      }, t('history_migrations', {
        count: entry.migrations
      })) : null);
    }));
  }
  outcome(entry) {
    if (entry.state === 'rolled-back') return 'undone';
    if (entry.state === 'failed') return 'failed';
    return entry.mode === 'install' ? 'installed' : entry.mode === 'remove' ? 'removed' : 'updated';
  }
  tone(state) {
    return state === 'done' ? ' Millwright-tag--ok' : state === 'failed' ? ' Millwright-tag--warn' : ' Millwright-tag--muted';
  }
}
flarum.reg.add('ernestdefoe-millwright', 'admin/components/HistoryTab', HistoryTab);